import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"VLESS（XTLS Vision Seed）","description":"","frontmatter":{},"headers":[],"relativePath":"ru/config/outbounds/vless.md","filePath":"ru/config/outbounds/vless.md","lastUpdated":1785781094000}`),a={name:`ru/config/outbounds/vless.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="vless-xtls-vision-seed" tabindex="-1">VLESS（XTLS Vision Seed） <a class="header-anchor" href="#vless-xtls-vision-seed" aria-label="Permalink to “VLESS（XTLS Vision Seed）”">​</a></h1><p>VLESS - это легкий транспортный протокол без сохранения состояния, который разделен на входящую и исходящую части и может служить мостом между клиентом и сервером Xray.</p><p>В отличие от <a href="./vmess.html">VMess</a>, VLESS не зависит от системного времени, аутентификация также осуществляется с помощью UUID.</p><h2 id="outboundconfigurationobject" tabindex="-1">OutboundConfigurationObject <a class="header-anchor" href="#outboundconfigurationobject" aria-label="Permalink to “OutboundConfigurationObject”">​</a></h2><p><code>OutboundConfigurationObject</code> соответствует элементу <code>settings</code> в <a href="./../outbound.html"><code>OutboundObject</code></a>.</p><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus has-focused-lines" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;outbounds&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: [</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    {</span></span>
<span class="line"><span style="--shiki-dark:#6A9955;--shiki-light:#008000;">      // ...</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;protocol&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;vless&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;settings&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {</span></span>
<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">        &quot;address&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;example.com&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">        &quot;port&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">443</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">        &quot;id&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;5783a3e7-e373-51cd-8642-c83782b807c5&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">        &quot;encryption&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;none&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">        &quot;flow&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;xtls-rprx-vision&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">        &quot;level&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">0</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">        &quot;reverse&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {}</span></span>
<span class="line has-focus"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">      }</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    }</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">  ]</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>VLESS должен использоваться с внешним уровнем транспортной защиты; <code>streamSettings.security: &quot;none&quot;</code> допустимо только тогда, когда адрес другой стороны является private-адресом (например, частным IP-адресом или частным доменным именем) и сам канал находится в доверенной сети, либо при включенном <code>VLESS Encryption</code>.</p></div><blockquote><p><code>address</code>: address</p></blockquote><p>Адрес сервера, указывающий на сервер, поддерживаются доменные имена, IPv4 и IPv6.</p><blockquote><p><code>port</code>: number</p></blockquote><p>Порт сервера, обычно тот же, что и порт, прослушиваемый сервером.</p><blockquote><p><code>id</code>: string</p></blockquote><p>Идентификатор пользователя VLESS, может быть любой строкой длиной менее 30 байт или допустимым UUID. Пользовательская строка и ее UUID-отображение эквивалентны, это означает, что вы можете использовать следующие способы записи id в файле конфигурации для идентификации одного и того же пользователя:</p><ul><li>Напишите <code>&quot;id&quot;: &quot;Я люблю арбуз учителя 1314&quot;</code>,</li><li>Или напишите <code>&quot;id&quot;: &quot;5783a3e7-e373-51cd-8642-c83782b807c5&quot;</code> (этот UUID является UUID-отображением строки &quot;Я люблю арбуз учителя 1314&quot;)</li></ul><p>Стандарт сопоставления описан в <a href="https://github.com/XTLS/Xray-core/issues/158" target="_blank" rel="noreferrer">VLESS UUID Mapping Standard: Mapping Custom Strings to a UUIDv5</a>.</p><p>Вы можете использовать команду <code>xray uuid -i &quot;Пользовательская строка&quot;</code> для генерации UUID, соответствующего пользовательской строке. Вы также можете использовать команду <code>xray uuid</code> для генерации случайного UUID.</p><blockquote><p><code>encryption</code>: string</p></blockquote><p>Настройки <a href="https://github.com/XTLS/Xray-core/pull/5067" target="_blank" rel="noreferrer">шифрования VLESS</a>. Не может быть пустым, для отключения необходимо явно установить значение <code>&quot;none&quot;</code>.</p><p>Большинству пользователей рекомендуется использовать команду <code>xray vlessenc</code> для автоматической генерации этого поля, чтобы избежать ошибок. Подробные настройки ниже рекомендуются только для продвинутых пользователей.</p><details class="details custom-block"><summary>Подробная конфигурация</summary><p>Его формат представляет собой строку подробных настроек, соединенных символом <code>.</code>. Например, <code>mlkem768x25519plus.native.0rtt.100-111-1111.75-0-111.50-0-3333.ptjHQxBQxTJ9MWr2cd5qWIflBSACHOevTauCQwa_71U</code>. В этом документе отдельная часть, разделенная точкой, называется блоком.</p><ul><li>Первый блок, это метод рукопожатия, в настоящее время он может быть только <code>mlkem768x25519plus</code>. Требуется, чтобы сервер и клиент совпадали.</li><li>Второй блок, это внешний вид трафика, возможные варианты: <code>native</code>/<code>xorpub</code>/<code>random</code>, которые соответствуют: пакет данных в исходном формате / исходный формат + обфускация части открытого ключа / полностью случайное число (подобно VMESS/Shadowsocks). Требуется, чтобы сервер и клиент совпадали.</li><li>Третий блок, это восстановление сеанса. Выбор <code>0rtt</code> будет следовать настройкам сервера, пытаясь использовать ранее сгенерированный тикет для пропуска рукопожатия и быстрого подключения (может быть вручную отключено сервером). Выбор <code>1rtt</code> принудительно выполнит процесс рукопожатия 1 RTT. Здесь это отличается по смыслу от настроек сервера; подробности см. в настройках <code>decryption</code> для входящих соединений VLESS.</li></ul><p>Далее идет padding (заполнение). После установления соединения клиент отправляет некоторые &quot;мусорные&quot; данные для маскировки характеристик длины. Он не обязан совпадать с сервером (совпадающая часть для входящего трафика - это padding, отправляемый сервером в сторону клиента). Это переменная часть, формат: <code>padding.delay.padding</code>+<code>(.delay.padding)</code>*n (можно вставлять несколько padding, но требуется, чтобы между двумя блоками padding обязательно был блок delay). Например, можно написать очень длинную строку <code>padding.delay.padding.delay.padding.delay.padding.delay.padding.delay.padding</code>.</p><ul><li>Формат <code>padding</code>: <code>probability-min-max</code>, например, <code>100-111-1111</code>, что означает отправку padding длиной 111~1111 с вероятностью 100%.</li><li>Формат <code>delay</code> также <code>probability-min-max</code>, например, <code>75-0-111</code>, что означает ожидание 0~111 миллисекунд с вероятностью 75%.</li></ul><p>Первый блок padding имеет особые требования: вероятность должна быть 100%, а минимальная длина должна быть больше 0. Если padding отсутствует, ядро автоматически использует <code>100-111-1111.75-0-111.50-0-3333</code> в качестве настроек padding.</p><p>Последний блок будет распознан ядром как параметр, используемый для аутентификации сервера. Он может быть сгенерирован с помощью <code>./xray x25519</code> (используя часть Password) или <code>./xray mlkem768</code> (используя часть Client) и должен соответствовать серверу. <code>mlkem768</code> является постквантовым алгоритмом, который может предотвратить (в будущем) компрометацию параметров клиента и использование квантового компьютера для взлома закрытого ключа и выдачи себя за сервер. Этот параметр используется только для проверки, сам процесс рукопожатия в любом случае является постквантово-безопасным, и существующие зашифрованные данные не могут быть взломаны будущими квантовыми компьютерами.</p></details><blockquote><p><code>flow</code>: string</p></blockquote><p>Режим управления потоком, используется для выбора алгоритма XTLS.</p><p>В настоящее время для исходящего протокола доступны следующие режимы управления потоком:</p><ul><li>Отсутствует <code>flow</code> или пустая строка: используется обычный TLS-прокси.</li><li><code>xtls-rprx-vision</code>：Использует XTLS, включает случайное заполнение внутреннего рукопожатия. Перехватывает UDP-трафик на порт 443 (QUIC), побуждая браузеры использовать обычный HTTPS для увеличения объема трафика, к которому может быть применен Splice.</li><li><code>xtls-rprx-vision-udp443</code>：Аналогичен <code>xtls-rprx-vision</code>, но не перехватывает UDP 443. Используется в случаях, когда программы принудительно используют QUIC, и перехват приводит к их неработоспособности.</li></ul><p>XTLS доступен только в следующих комбинациях</p><ul><li>TCP+TLS/REALITY: если в данный момент передаётся TLS 1.3, ядро попытается выполнить Splice на зашифрованных данных нижнего уровня; в случае успеха это позволит сэкономить все IO-затраты ядра.</li><li>VLESS Encryption: не имеет ограничений по нижнему уровню транспорта. Если нижний уровень не TCP, будет предпринята только попытка «прозрачного» прохождения Encryption, что сэкономит накладные расходы Encryption; если же используется TCP, всё равно будет предпринята попытка выполнения Splice.</li></ul><div class="tip custom-block"><p class="custom-block-title">О Splice</p><p>Splice - это функция, предоставляемая ядром Linux, где ядро системы напрямую пересылает TCP, минуя память Xray, что значительно сокращает количество операций копирования данных и переключения контекста процессора.</p><p>Ограничения использования режима Splice:</p><ul><li>Среда Linux.</li><li>Входящий протокол: <code>Dokodemo door</code>, <code>Socks</code>, <code>HTTP</code> и другие чистые TCP-соединения или другие входящие протоколы, использующие XTLS.</li><li>Исходящий протокол: VLESS + XTLS.</li></ul><p>При использовании Splice отображение скорости сети происходит с задержкой: статистика учитывается только после разрыва соединения, так как в период, когда ядро управляет соединением, Xray не имеет информации о проходящем трафике.</p></div><blockquote><p><code>level</code>: number</p></blockquote><p>Уровень пользователя, для соединения будет использоваться <a href="./../policy.html#levelpolicyobject">локальная политика</a>, соответствующая этому уровню пользователя.</p><p>Значение level соответствует значению <code>level</code> в разделе <a href="./../policy.html#policyobject">policy</a>. Если не указано, используется значение по умолчанию - 0.</p><blockquote><p><code>reverse</code>: struct</p></blockquote><p>Упрощённая конфигурация обратного прокси VLESS. При этом сохраняет информацию о реальном исходном IP-адресе со стороны публичной сети.</p><p>Наличие этого параметра означает, что данное исходящее соединение может быть использовано как исходящее соединение обратного прокси VLESS. Оно автоматически установит соединение с сервером для регистрации туннеля обратного прокси.</p><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;reverse&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">    &quot;tag&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;r-inbound&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">    &quot;sniffing&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: {}</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">  }</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>tag</code> — это тег входящего прокси для данного обратного прокси. Когда сервер отправляет запрос обратного прокси, он войдет в систему маршрутизации через входящее соединение с этим тегом. Используйте систему маршрутизации, чтобы направить его на нужное вам исходящее соединение.</p><p>Используемый UUID должен совпадать с UUID, для которого на сервере также настроен <code>reverse</code> (подробнее см. в разделе о входящих соединениях VLESS).</p><p><code>sniffing</code> см. <a href="./../inbound.html#sniffingobject">sniffingObject</a> — выполняет распознавание (sniffing) запросов, поступающих через этот обратный прокси.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Полное руководство: <a href="./../../document/level-2/vless_reverse.html">Примеры обратного проксирования VLESS</a></p></div>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};